package com.nequard.community;
import com.nequard.auth.OrganizationAccessService;import com.nequard.auth.UserRepository;import org.springframework.security.core.Authentication;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/community/reputation") public class ReputationController{private final ReputationRepository repo;private final OrganizationAccessService access;private final UserRepository users;public ReputationController(ReputationRepository r,OrganizationAccessService a,UserRepository u){repo=r;access=a;users=u;}
@GetMapping("/{userId}")public Reputation get(Authentication a,@PathVariable UUID userId){var u=users.findById(userId).orElseThrow(()->new NoSuchElementException("USER_NOT_FOUND"));if(!access.canAccess(a,u.getOrganizationId()))throw new SecurityException("TENANT_ACCESS_DENIED");return repo.findByUserId(userId).orElseGet(()->{Reputation x=new Reputation();x.setUserId(userId);x.setOrganizationId(u.getOrganizationId());return repo.save(x);});}
@PutMapping("/{userId}")@PreAuthorize("hasAnyRole('SUPER_ADMIN','NETWORK_ADMIN','COMMUNITY_ADMIN')")public Reputation update(Authentication a,@PathVariable UUID userId,@RequestBody Reputation x){var u=users.findById(userId).orElseThrow(()->new NoSuchElementException("USER_NOT_FOUND"));UUID org=access.requireOrganization(a,u.getOrganizationId());x.setUserId(userId);x.setOrganizationId(org);return repo.save(x);}}